<http://example.org/ns/flute_music_style> a ns2:CACAO_0000012 ;
    schema:description "A style of single-pitch flute music documented in northeast Lithuania, mainly in the first half of the 20th century, though likely older and more widespread previously. Currently exists in the folk music revival movement's repertoire." .

<http://example.org/ns/skuduciai> a ns2:CACAO_0000025 ;
    schema:description "Single-pitch flutes, typically consisting of four to eight flutes in a set. Played by one to two instruments per participant in an ensemble. Pipes are 10 to 20 cm long and can be made of chervil, reed, goutweed, acorn, berry-bearing alder, ashwood, or garden willows." .

<http://example.org/ns/ragai> a ns2:CACAO_0000025 ;
    schema:description "Wooden trumpets played in northeast Lithuania in homogenous ensemble settings, alongside skuduciai. Their repertoire was very similar to that of the skuduciai." .

<http://example.org/ns/northeast_lithuania> a schema:AdministrativeArea, ns3:E53_Place ;
    schema:name "Northeast Lithuania" .

<http://example.org/ns/lithuanian_latvian_border> a ns3:E53_Place ;
    schema:description "A small territory on the Lithuanian-Latvian border where the single-pitch flute music style was documented." .

<http://example.org/ns/folk_music_revival_movement> a ns2:CACAO_0000010 ;
    schema:name "Folk music revival movement" .

