<http://example.org/ns/adolfas_sabaliauskas> a schema:Person, ns3:E39_Actor ;
    schema:name "Adolfas Sabaliauskas" ;
    schema:birthDate "1873" ;
    schema:deathDate "1950" ;
    schema:description "Collector who stated in 1916 that 'Today one plays the skuduciai standing, but once one also played them while walking.'" .

<http://example.org/ns/skuduciai_ragai_notation> a ns3:E33_Linguistic_Object ;
    schema:description "A special oral notation for the music of skuduciai and ragai using certain syllable combinations for instruction and memorization." .

<http://example.org/ns/single_pitch_flute_music_characteristics> a ns3:E28_Conceptual_Object ;
    schema:description "Characteristics include polyrhythmic organization, harmony rich in seconds, and use of a limited number of rhythmic values (quavers and crotchets), common with northeast Lithuanian vocal polyphony of the startines." .

<http://example.org/ns/startines> a ns2:CACAO_0000027 ;
    schema:name "startines" ;
    schema:description "A kind of Schwebungsdiaphonie, which is a form of northeast Lithuanian vocal polyphony." .

<http://example.org/ns/first_piece_documentation> a foaf:Document ;
    schema:description "Written documentation about one of the two pieces presented, noting it represents a song played on skuduciai." .

<http://example.org/ns/second_piece_documentation> a foaf:Document ;
    schema:description "Written documentation about one of the two pieces presented, noting that it used material of vocal origin only as a basis or source of inspiration." .

<http://example.org/ns/first_piece_music> a ns2:CACAO_0000089 ;
    schema:name "First piece of music" ;
    schema:description "Possibly a sutartine song performed instrumentally. Features two musicians, each playing a pair of flutes. The recording has 22 two-measure sections, with variations only in intro/closing. Main musical material appears in the third section and repeats without variation until the final section." .

<http://example.org/ns/second_piece_music> a ns2:CACAO_0000089 ;
    schema:name "Second piece of music" ;
    schema:description "Performed by three musicians, one playing two flutes, the others one each. Recording consists of 18 sections, mostly two measures long. Contains four larger formal units." .

<http://example.org/ns/edouard_wolter> a schema:Person, ns3:E39_Actor ;
    schema:name "Eduard Wolter" ;
    schema:birthDate "1856" ;
    schema:deathDate "1941" ;
    schema:description "Linguist, folklorist, ethnographer, and historian of literature. Author of numerous studies on Lithuanian language and mythology, and on Lithuanian and Latvian folk-lore. Made two recordings in 1909 in Juzintai, northeast Lithuania." .

